    /**
     * Approximate the number of tokens in [text] using byte-level BPE.
     * Each UTF-8 byte starts as its own token, then each merge rule
     * greedily combines adjacent byte pairs. The remaining byte count
     * after all merges = token count.
     */
    fun count(text: String): Int {
        if (text.isEmpty()) return 0
        val bytes = text.encodeToByteArray()
        val tokens = mutableListOf<IntArray>()
        for (b in bytes) tokens.add(intArrayOf(b.toInt() and 0xFF))
        
        // Apply each merge rule greedily, repeating until no more merges
        var changed = true
        while (changed) {
            changed = false
            val merged = mutableListOf<IntArray>()
            var i = 0
            while (i < tokens.size - 1) {
                val a = tokens[i], b = tokens[i + 1]
                var matched = false
                // Check each merge pair (MERGES[2k] + MERGES[2k+1])
                for (k in 0..(MERGES.size / 2 - 1)) {
                    val left = MERGES[2 * k]
                    val right = MERGES[2 * k + 1]
                    if (a.contentEquals(left) && b.contentEquals(right)) {
                        merged.add(a + b)
                        i += 2
                        changed = true
                        matched = true
                        break
                    }
                }
                if (!matched) {
                    merged.add(a)
                    i++
                }
            }
            if (i < tokens.size) merged.add(tokens[i])
            tokens.clear()
            tokens.addAll(merged)
        }
        return tokens.size
    }
